    uint256 manaUsed;
    uint256 ethPerFeeAsset;
    uint256 congestionCost;
    uint256 proverCost;
}
struct CheckpointLog {
    bytes32 archive;
    bytes32 headerHash;
    bytes32 blobCommitmentsHash;
    bytes32 outHash;
    bytes32 attestationsHash;
    bytes32 payloadDigest;
    Slot slotNumber;
    FeeHeader feeHeader;
